using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Aster {
class PlanWindow:Form {
 readonly RepairPlan plan;TextBox text;Label title;bool running,stopPending;StringBuilder transcript=new StringBuilder();
 public PlanWindow(RepairPlan p){plan=p;Text="Aster · Approved repair plan";Size=new Size(940,680);BackColor=Color.FromArgb(16,23,32);ForeColor=Color.White;Font=new Font("Segoe UI",10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(15)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,65));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));Controls.Add(layout);title=new Label{Text=p.Title+"\r\n"+p.Description,Dock=DockStyle.Fill};layout.Controls.Add(title,0,0);text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,ReadOnly=true,BackColor=Color.FromArgb(23,33,45),ForeColor=Color.FromArgb(210,232,238),Font=new Font("Consolas",10)};layout.Controls.Add(text,0,1);var stop=new Button{Text="Stop after the current Windows tool finishes",Dock=DockStyle.Fill};stop.Click+=(s,e)=>{stopPending=true;stop.Enabled=false;Append("Remaining steps canceled. The current tool will be allowed to finish.");};layout.Controls.Add(stop,0,2);Shown+=async(s,e)=>await Run();FormClosing+=(s,e)=>{if(running){e.Cancel=true;MessageBox.Show(this,"A Windows tool is running. Use Stop after current tool, then wait for completion.");}};}
 void Append(string line){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Append),line);return;}line=(line??"").Replace("\0","");transcript.AppendLine(line);text.AppendText(line+Environment.NewLine);}
 public static bool ContinueAfter(int exitCode){return exitCode==0;}
 async Task Run(){running=true;string outcome="Plan completed; review the Windows tool output. No automatic claim of repair success is made.";try{Append("APPROVED PLAN: "+plan.Title+" · "+DateTime.Now);for(int i=0;i<plan.Jobs.Length;i++){if(stopPending){outcome="Stopped before remaining steps.";break;}var job=RecoveryJob.Find(plan.Jobs[i]);if(job==null)throw new Exception("Plan contains an unsupported operation.");title.Text="Step "+(i+1)+" / "+plan.Jobs.Length+" · "+job.Title+"\r\nNo automatic reboot. Remaining steps stop if this tool fails.";Append("\r\n> "+job.FileName+" "+job.Arguments);using(var process=new Process{StartInfo=new ProcessStartInfo(job.FileName,job.Arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){if(job.Exe=="sfc.exe")process.StartInfo.StandardOutputEncoding=Encoding.Unicode;process.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();await Task.Run(()=>process.WaitForExit());Append("Exit code: "+process.ExitCode);if(!ContinueAfter(process.ExitCode)){outcome=process.ExitCode==3010?"Windows reports a restart is required. Remaining steps were not run. Save work and restart manually.":"This step returned a nonzero exit code. Remaining steps were not run. Review the output.";break;}}}Append("\r\n"+outcome);Append("After addressing any reported issue, run the advisor scan again and test your original symptom.");}catch(Exception ex){outcome="Plan stopped: "+ex.Message;Append(outcome);}finally{running=false;try{string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","RecoveryLogs");Directory.CreateDirectory(dir);string path=Path.Combine(dir,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-plan-"+plan.Id+".txt");File.WriteAllText(path,transcript.ToString(),Encoding.UTF8);title.Text=outcome+"\r\nLog: "+path;}catch(Exception ex){title.Text=outcome+"\r\nLog could not be saved: "+ex.Message;}}}
}
}

